function getDrugAliasKey(d){
    const n = String(d.generic_name||'').toLowerCase();
    const t = String(d.trade_names||'').toLowerCase();
    return Object.keys(DRUG_ALIAS_MAP).find(k => n.includes(k) || t.includes(k)) || '';
}

function drugSearchText(d){
    const key = getDrugAliasKey(d);
    return [
        d.generic_name, d.trade_names, d.indication, d.conditions, d.price_unit,
        d.aliases, key, (DRUG_ALIAS_MAP[key] || []).join(' ')
    ].filter(Boolean).join(' ').toLowerCase();
}

