function dispatchCompatEvent(el, type){
    if(!el) return false;
    let ev;
    try {
        ev = new Event(type, {bubbles:true});
    } catch(e){
        ev = document.createEvent('Event');
        ev.initEvent(type, true, false);
    }
    return el.dispatchEvent(ev);
}
function dispatchCompatClick(el){
    if(!el) return false;
    if(typeof el.click === 'function'){
        el.click();
        return true;
    }
    let ev;
    try {
        ev = new MouseEvent('click', {bubbles:true, cancelable:true, view:window});
    } catch(e){
        ev = document.createEvent('MouseEvents');
        ev.initMouseEvent('click', true, true, window, 1, 0, 0, 0, 0, false, false, false, false, 0, null);
    }
    return el.dispatchEvent(ev);
}
function legacyTouchActivationTarget(target){
    let el = target;
    const clickableClasses = {
        'dept-card':1, 'filter-chip':1, 'icd-q':1, 'icd-code':1,
        'ajcc-tab-card':1, 'ajcc-qchip':1, 'ws-tab-card':1, 'ws-qchip':1,
        'touch-picker':1, 'touch-presets':1, 'calc-tab':1, 'cond-btn':1,
        'inp-reg-btn':1, 'reg-card':1, 'drug-item':1, 'modal-dashboard-card':1,
        'settings-row':1, 'ws-btn':1, 'btn':1
    };
    while(el && el !== document && el.nodeType === 1){
        const tag = (el.tagName || '').toUpperCase();
        if(tag === 'INPUT' || tag === 'SELECT' || tag === 'TEXTAREA' || tag === 'LABEL' || tag === 'OPTION') return null;
        if(tag === 'A' && el.getAttribute('href')) return null;
        if(el.getAttribute && el.getAttribute('onclick') !== null) return el;
        if(el.classList){
            for(const name in clickableClasses){
                if(el.classList.contains(name)) return el;
            }
        }
        el = el.parentNode;
    }
    return null;
}
let _legacyTouchStart = null;
function bindLegacySafariTouchActivation(){
    if(window._nhiLegacyTouchActivationBound) return;
    if(!('ontouchstart' in window) && !(navigator.maxTouchPoints > 0)) return;
    window._nhiLegacyTouchActivationBound = true;
    document.addEventListener('touchstart', function(event){
        const touch = event.touches && event.touches.length === 1 ? event.touches[0] : null;
        if(!touch) {
            _legacyTouchStart = null;
            return;
        }
        _legacyTouchStart = {
            x: touch.clientX,
            y: touch.clientY,
            t: Date.now(),
            target: event.target
        };
    }, false);
    document.addEventListener('touchend', function(event){
        if(!_legacyTouchStart) return;
        const touch = event.changedTouches && event.changedTouches[0];
        if(!touch) return;
        const dx = Math.abs(touch.clientX - _legacyTouchStart.x);
        const dy = Math.abs(touch.clientY - _legacyTouchStart.y);
        const elapsed = Date.now() - _legacyTouchStart.t;
        const target = legacyTouchActivationTarget(_legacyTouchStart.target);
        _legacyTouchStart = null;
        if(!target || dx > 14 || dy > 14 || elapsed > 900) return;
        event.preventDefault();
        dispatchCompatClick(target);
    }, false);
}

