function dashboardLayoutForDesigner(widget, layout){
    const fallback = dashboardDefaultSize(widget);
    const saved = (layout && layout[widget.id]) || {};
    const size = { ...fallback, ...saved };
    const maxWidth = Math.max(420, Math.min(1160, window.innerWidth - 48));
    return {
        x: Math.max(0, snapDashboard(Number(size.x) || 0)),
        y: Math.max(60, snapDashboard(Number(size.y) || 80)),
        w: Math.max(220, snapDashboard(Math.min(Number(size.w) || fallback.w, maxWidth))),
        h: Math.max(110, snapDashboard(Number(size.h) || fallback.h))
    };
}
