function prepareDashboardLayoutNodes(){
    document.querySelectorAll('.dashboard-layout-node').forEach(node => {
        if(node.dataset.dragReady === '1') return;
        node.dataset.dragReady = '1';
        const start = (clientX, clientY, mode, event) => {
            const id = node.dataset.widgetId;
            const rect = node.getBoundingClientRect();
            const canvas = document.getElementById('dashboardLayoutCanvas');
            if(!id || !canvas) return;
            _dashboardDesignerDrag = {
                id: id,
                node: node,
                canvas: canvas,
                mode: mode,
                startClientX: clientX,
                startClientY: clientY,
                startX: parseInt(node.style.left, 10) || 0,
                startY: parseInt(node.style.top, 10) || 0,
                startW: rect.width,
                startH: rect.height
            };
            node.classList.add('dragging');
            if(event && event.preventDefault) event.preventDefault();
        };
        const move = (clientX, clientY) => {
            if(!_dashboardDesignerDrag || _dashboardDesignerDrag.node !== node) return;
            const dx = clientX - _dashboardDesignerDrag.startClientX;
            const dy = clientY - _dashboardDesignerDrag.startClientY;
            if(_dashboardDesignerDrag.mode === 'resize'){
                const w = Math.max(220, snapDashboard(_dashboardDesignerDrag.startW + dx));
                const h = Math.max(110, snapDashboard(_dashboardDesignerDrag.startH + dy));
                node.style.width = `${w}px`;
                node.style.height = `${h}px`;
                const size = node.querySelector('.dashboard-layout-node-size');
                if(size) size.textContent = `${w} × ${h}`;
            } else {
                node.style.left = `${Math.max(0, snapDashboard(_dashboardDesignerDrag.startX + dx))}px`;
                node.style.top = `${Math.max(60, snapDashboard(_dashboardDesignerDrag.startY + dy))}px`;
            }
            growDashboardDesignerCanvas();
        };
        const finish = () => {
            if(!_dashboardDesignerDrag || _dashboardDesignerDrag.node !== node) return;
            const patch = {
                x: parseInt(node.style.left, 10) || 0,
                y: parseInt(node.style.top, 10) || 80,
                w: parseInt(node.style.width, 10) || 320,
                h: parseInt(node.style.height, 10) || 160
            };
            saveDashboardWidgetLayout(node.dataset.widgetId, patch);
            node.classList.remove('dragging');
            _dashboardDesignerDrag = null;
        };
        const modeFromTarget = target => target && target.dataset && target.dataset.resize === '1' ? 'resize' : 'move';
        if(window.PointerEvent){
            node.addEventListener('pointerdown', event => {
                start(event.clientX, event.clientY, modeFromTarget(event.target), event);
                try { if(node.setPointerCapture) node.setPointerCapture(event.pointerId); } catch(e){}
            });
            node.addEventListener('pointermove', event => move(event.clientX, event.clientY));
            node.addEventListener('pointerup', event => {
                finish();
                try { if(node.releasePointerCapture) node.releasePointerCapture(event.pointerId); } catch(e){}
            });
            node.addEventListener('pointercancel', finish);
        } else {
            node.addEventListener('mousedown', event => start(event.clientX, event.clientY, modeFromTarget(event.target), event));
            document.addEventListener('mousemove', event => move(event.clientX, event.clientY));
            document.addEventListener('mouseup', finish);
            node.addEventListener('touchstart', event => {
                const touch = event.touches && event.touches[0];
                if(touch) start(touch.clientX, touch.clientY, modeFromTarget(event.target), event);
            }, { passive:false });
            document.addEventListener('touchmove', event => {
                const touch = event.touches && event.touches[0];
                if(touch){
                    move(touch.clientX, touch.clientY);
                    if(_dashboardDesignerDrag && event.preventDefault) event.preventDefault();
                }
            }, { passive:false });
            document.addEventListener('touchend', finish);
            document.addEventListener('touchcancel', finish);
        }
    });
}
function growDashboardDesignerCanvas(){
    const canvas = document.getElementById('dashboardLayoutCanvas');
    if(!canvas) return;
    let maxRight = 1180;
    let maxBottom = 780;
    canvas.querySelectorAll('.dashboard-layout-node').forEach(node => {
        const x = parseInt(node.style.left, 10) || 0;
        const y = parseInt(node.style.top, 10) || 0;
        const w = parseInt(node.style.width, 10) || 0;
        const h = parseInt(node.style.height, 10) || 0;
        maxRight = Math.max(maxRight, x + w + 24);
        maxBottom = Math.max(maxBottom, y + h + 24);
    });
    canvas.style.width = `${maxRight}px`;
    canvas.style.height = `${maxBottom}px`;
}
