    if(p.brca && p.brca !== 'wt') items.push(String(p.brca).toUpperCase());
    if(p.esr1 === 'mut') items.push('ESR1');
    if(p.pik3ca === 'mut' || p.pik3ca === '+') items.push('PIK3CA');
