function dashboardPredictSurvivalSummary(p, erSign, age, size, nodes, grade, ki67){
    if(!age || !size || Number.isNaN(nodes) || !grade || !erSign || !p.her2) return null;
    if(age < 25 || age > 85 || size < 1) return null;
    const isERpos = erSign === '+';
    const her2tok = p.her2 === '+' ? 'pos' : ((p.her2 === '-' || p.her2 === 'low') ? 'neg' : 'unk');
    const ki67tok = typeof ki67 === 'number' && !Number.isNaN(ki67) ? (ki67 >= 10 ? 'pos' : 'neg') : 'unk';
    const mode = readDashboardSelectValue('pred_mode', p.predict_mode || '');
    const year = readDashboardSelectNumber('pred_year', p.diagnosis_year || '');
    if(!['symp','screen','other'].includes(mode)) return null;
    if(!Number.isFinite(Number(year)) || Number(year) < 2000 || Number(year) > 2030) return null;
    const smoker = readDashboardSelectValue('pred_smoker', p.smoker || 'unk');
    const prFromForm = readDashboardSelectValue('pred_pr', '');
    const prSign = prFromForm === 'pos' ? '+' : (prFromForm === 'neg' ? '-' : _markerSign(p.pr));
    const pi = isERpos
        ? _predictPI_ERpos(age, size, nodes, grade, mode, her2tok, ki67tok)
        : _predictPI_ERneg(age, size, nodes, grade, mode, her2tok);
    const mi = _predictMI(age);
    const endo = readDashboardSelectNumber('pred_endo', 0);
    const chemo = readDashboardSelectNumber('pred_chemo', 0);
    const trast = readDashboardSelectNumber('pred_trast', 0);
    const bis = readDashboardSelectNumber('pred_bis', 0);
    const rt = readDashboardSelectNumber('pred_rt', 0);
    const heartDose = Math.max(0, readDashboardSelectNumber('pred_rt_heart_dose', 0));
    const menopause = readDashboardSelectValue('pred_menopause', p.menopause || '');
    let txBcLogHR = 0;
    let txOcLogHR = 0;
    if(isERpos && endo >= 5) txBcLogHR += -0.3857;
    if(chemo === 2){
        txBcLogHR += -0.248;
        txOcLogHR += 0.183;
    } else if(chemo === 3){
        txBcLogHR += -0.446;
        txOcLogHR += 0.183;
    }
    if(her2tok === 'pos' && trast === 1) txBcLogHR += -0.3567;
    if(bis === 1 && menopause === 'post') txBcLogHR += -0.198;
    if(rt === 1){
        txBcLogHR += -0.180;
        txOcLogHR += 0.078 * heartDose;
    }
    const years = [5, 10, 15];
    const computeSurvYears = (bcTx, ocTx) => {
        const cumBC0 = [], cumOC0 = [];
        for(let t = 1; t <= 15; t++){
            cumBC0.push(_predictBaseCumBC(t, isERpos));
            cumOC0.push(_predictBaseCumOC(t));
        }
        const annBC0 = cumBC0.map((v, i) => i === 0 ? v : v - cumBC0[i - 1]);
        const annOC0 = cumOC0.map((v, i) => i === 0 ? v : v - cumOC0[i - 1]);
        const annBC = annBC0.map(v => v * Math.exp(pi + bcTx));
        const annOC = annOC0.map(v => v * Math.exp(mi + ocTx));
        const surv = [];
        let cumBC = 0;
        let cumOC = 0;
        annBC.forEach((v, i) => {
            cumBC += v;
            cumOC += annOC[i];
            surv.push(Math.exp(-cumBC) * Math.exp(-cumOC) * 100);
        });
        return years.map(y => surv[y - 1]);
    };
    const v2Base = computeSurvYears(0, 0);
    const v2Treated = computeSurvYears(txBcLogHR - (rt === 1 ? -0.180 : 0), 0);
    const v3BaseModel = _predictV3Survival({
        year, age, smoker,
        er: isERpos ? 1 : 0,
        pr: prSign === '+' ? 1 : (prSign === '-' ? 0 : null),
        her2: her2tok === 'pos' ? 1 : (her2tok === 'neg' ? 0 : null),
        ki67: ki67tok === 'pos' ? 1 : (ki67tok === 'neg' ? 0 : null),
        size, grade, nodes,
        screen: _predictScreenVal(mode),
        radio: 0, heartGy: 0, horm: 0, gen: 0, traz: 0, bis: 0
    });
    const v3TreatedModel = _predictV3Survival({
        year, age, smoker,
        er: isERpos ? 1 : 0,
        pr: prSign === '+' ? 1 : (prSign === '-' ? 0 : null),
        her2: her2tok === 'pos' ? 1 : (her2tok === 'neg' ? 0 : null),
        ki67: ki67tok === 'pos' ? 1 : (ki67tok === 'neg' ? 0 : null),
        size, grade, nodes,
        screen: _predictScreenVal(mode),
        radio: rt === 1 ? 1 : 0,
        heartGy: rt === 1 ? heartDose : 0,
        horm: isERpos && endo >= 5 ? 1 : 0,
        gen: chemo,
        traz: her2tok === 'pos' && trast === 1 ? 1 : 0,
        bis: bis === 1 && menopause === 'post' ? 1 : 0
    });
    const base = v3BaseModel ? years.map(y => v3BaseModel.baselinePct[y - 1]) : v2Base;
    const treated = v3TreatedModel ? years.map(y => v3TreatedModel.treatedPct[y - 1]) : v2Treated;
    return {
        years,
        base,
        treated,
        v2Treated,
        v3Treated: treated,
        v2Benefit: v2Treated.map((v, i) => v - v2Base[i]),
        benefit: treated.map((v, i) => v - base[i]),
        chemo,
        chemoLabel: dashboardPredictChemoLabel(chemo),
        rt: rt === 1,
        heartDose
    };
}
