    const inferredNodes = predictNodeCountFromStage(st.N);
    const nodes = p.nodes_pos !== '' ? Number(p.nodes_pos) : (inferredNodes !== '' ? Number(inferredNodes) : NaN);
    const age = Number(p.age);
