function dashboardAgentEntryHtml(entry){
    const role = entry && entry.role === 'user' ? 'user' : 'agent';
    const response = entry ? entry.response : '';
    if(role === 'user') return `<div class="dashboard-agent-msg user">${esc(String(response || ''))}</div>`;
    return `<div class="dashboard-agent-msg agent">${dashboardAgentResponseHtml(response)}</div>`;
}
function dashboardAgentHistoryHtml(){
    return dashboardAgentReadHistory().map(dashboardAgentEntryHtml).join('');
}
function dashboardAgentScrollBottom(){
    const thread = document.getElementById('dashboardAgentThread');
    if(thread) thread.scrollTop = thread.scrollHeight;
}
function dashboardAgentAddMessage(role, text, persist=true){
    const thread = document.getElementById('dashboardAgentThread');
    if(!thread) return null;
    const div = document.createElement('div');
    div.className = `dashboard-agent-msg ${role === 'user' ? 'user' : 'agent'}`;
    if(role === 'user') div.textContent = text;
    else div.innerHTML = dashboardAgentResponseHtml(text);
    thread.appendChild(div);
    if(persist) dashboardAgentPushHistory(role, text);
    dashboardAgentRefreshContextMeter();
    dashboardAgentScrollBottom();
    return div;
}
function dashboardAgentAsk(text){
    const input = document.getElementById('dashboardAgentInput');
    if(input) input.value = text;
    dashboardAgentSubmit();
}
function dashboardAgentInputKeydown(event){
    if(!event || event.key !== 'Enter' || event.shiftKey || event.ctrlKey || event.altKey || event.metaKey) return;
    event.preventDefault();
    dashboardAgentSubmit();
}
async function dashboardAgentSubmit(allowPhi=false){
    const input = document.getElementById('dashboardAgentInput');
    if(!input) return;
    const text = input.value.trim();
    if(!text) return;
    const phi = dashboardAgentDetectPhi(text);
    if(phi.hasPhi && !allowPhi){
        _dashboardAgentPhiLastScanText = text;
        dashboardAgentRenderPhiWarning(text, true);
        return;
    }
    if(phi.hasPhi && allowPhi && _dashboardAgentPhiLastScanText !== text){
        _dashboardAgentPhiLastScanText = text;
    }
    input.value = '';
    dashboardAgentRenderPhiWarning('');
    dashboardAgentAddMessage('user', text);
    dashboardAgentRefreshContextMeter();
    const pending = dashboardAgentAddMessage('agent', '__loading__', false);
    const external = await dashboardAgentTryExternal(text);
    const reply = external || dashboardAgentReply(text);
    if(pending) dashboardAgentRenderResponse(pending, reply);
    else dashboardAgentRenderResponse(dashboardAgentAddMessage('agent', '', false), reply);
    dashboardAgentRefreshContextMeter();
}
function dashboardAgentResponseHtml(response){
    if(!response || typeof response === 'string'){
        if(response === '__loading__'){
            return `<div class="dashboard-agent-loading"><span>處理中</span><i></i><i></i><i></i></div>`;
        }
        return esc(response || '');
    }
    const reply = String(response.reply || response.message || response.text || '').trim();
    const patch = response.patient_patch || response.patch || response.fields || null;
    const citations = Array.isArray(response.citations) ? response.citations : (Array.isArray(response.context) ? response.context : []);
    const calledTools = Array.isArray(response.called_tools) ? response.called_tools : [];
    let html = `<div>${esc(reply || '已處理。')}</div>`;
    if(response.action === 'apiGuide'){
        html += `<div class="dashboard-agent-action">
            <div>需要接入完整 agent API 才能取得工具化回答。</div>
            <button type="button" onclick="showApiGuide()">查看 API 接入說明</button>
        </div>`;
    }
    if(patch && typeof patch === 'object' && Object.keys(patch).length){
        const id = `patch_${++_dashboardAgentPatchSeq}`;
        _dashboardAgentPatches[id] = patch;
        const preview = Object.entries(patch)
            .filter(([key]) => key in PATIENT_DEFAULTS)
            .slice(0, 12)
            .map(([key, value]) => `${key}=${value}`)
            .join('、');
        html += `<div class="dashboard-agent-action">
            <div>可寫入欄位：${esc(preview || '沒有符合 workspace schema 的欄位')}</div>
            <button type="button" onclick="dashboardAgentApplyPatientPatch('${id}')">套用欄位</button>
        </div>`;
    }
    if(citations.length || calledTools.length){
        const toolTags = calledTools.slice(0, 5).map(t => `<span>tool:${esc(t)}</span>`).join('');
        const citeTags = citations.slice(0, 4).map(c => `<span>${esc(typeof c === 'string' ? c : (c.title || c.source || c.id || 'system'))}</span>`).join('');
        html += `<div class="dashboard-agent-citations">${toolTags}${citeTags}</div>`;
    }
    return html;
}
function dashboardAgentRenderResponse(target, response, persist=true){
    if(!target) return;
    target.innerHTML = dashboardAgentResponseHtml(response);
    if(persist) dashboardAgentPushHistory('agent', response);
    dashboardAgentRefreshContextMeter();
    dashboardAgentScrollBottom();
}
function dashboardAgentApplyPatientPatch(id){
    const patch = _dashboardAgentPatches[id];
    if(!patch || typeof patch !== 'object') return;
    const result = window.OncoBreastPatientContext
        ? window.OncoBreastPatientContext.applyPatch(_patient, patch, PATIENT_DEFAULTS, {
            axillary_surgery: normalizeAxillarySurgeryValue
        })
        : (() => {
            const appliedFallback = [];
            Object.entries(patch).forEach(([key, value]) => {
                if(!(key in PATIENT_DEFAULTS)) return;
                if(value === undefined || value === null || value === '') return;
                _patient[key] = key === 'axillary_surgery' ? normalizeAxillarySurgeryValue(value) : String(value);
                appliedFallback.push(key);
            });
            return { patient:_patient, applied:appliedFallback };
        })();
    _patient = result.patient;
    const applied = result.applied || [];
    if(!applied.length){
        dashboardAgentAddMessage('agent', '沒有可套用到 Patient Context 的欄位。');
        return;
    }
    normalizeWorkspaceNodeFields();
    normalizeWorkspaceStage();
    savePatient();
    syncWorkspaceInputs(applied.concat(['T','N','M','nodes_pos','nodes_total','pN']));
    refreshWorkspaceDerived();
    refreshDashboardResults();
    refreshInitialVisitChecklist();
    if(typeof syncWsQuickChips === 'function') syncWsQuickChips();
    syncAllCalculatorsFromWorkspaceIfActive();
    if(document.body.classList.contains('modal-dashboard-mode')) renderModalDashboardOverview();
    dashboardAgentAddMessage('agent', `已套用 ${applied.length} 個欄位：${applied.join('、')}。請確認欄位是否正確。`);
}
async function dashboardAgentTryExternal(text){
    const cfg = getDashboardAgentApiConfig();
    if(!cfg.enabled || !cfg.endpoint) return '';
    try {
        const ctx = dashboardPatientContext();
        const payload = window.OncoBreastAgentAdapter
            ? window.OncoBreastAgentAdapter.buildPayload({
                message: text,
                context: ctx,
                reportText: _dashboardAgentReportText || '',
                tools: DASHBOARD_AGENT_TOOLS,
                version: typeof APP_VERSION !== 'undefined' ? APP_VERSION : ''
            })
            : {
                message: text,
                patient_context: ctx.p || {},
                derived: { stage: ctx.stage || {}, subtype: ctx.subtype || '', missing: ctx.missing || [], phase_label: ctx.phaseLabel || '' },
                report_text: _dashboardAgentReportText || '',
                tool_registry: DASHBOARD_AGENT_TOOLS.map(t => ({ id:t.id, label:t.label, aliases:t.aliases || [] })),
                client: { app:'OncoBreast Calculator', version: typeof APP_VERSION !== 'undefined' ? APP_VERSION : '' }
            };
        const data = window.OncoBreastAgentAdapter
            ? await window.OncoBreastAgentAdapter.post(cfg, payload)
            : await (async () => {
                const res = await fetch(cfg.endpoint, {
                    method: 'POST',
                    headers: { 'content-type': 'application/json', 'x-client-app': 'oncobreast-copilot', ...cfg.headers },
                    body: JSON.stringify(payload)
                });
                if(!res.ok) return null;
                return await res.json().catch(() => ({}));
            })();
        if(!data) return '';
        if(data.tool_id && dashboardAgentShouldOpenTool(text)) dashboardAgentRunTool(data.tool_id);
        return data && typeof data === 'object' ? data : String(data.reply || data.message || data.text || '').trim();
    } catch(e){
        console.warn('Dashboard agent external API failed', e);
        return '';
    }
}
function dashboardAgentPathologySummary(text, sourceLabel){
    _dashboardAgentReportText = String(text || '');
    const result = parseWorkspacePathologyReport(_dashboardAgentReportText);
    _lastPathologyParse = result;
    const box = document.getElementById('ws_pathology_text');
    if(box) box.value = _dashboardAgentReportText;
    renderWorkspacePathologyParse(result, false);
    const fields = Object.entries(result.fields || {});
    const names = fields.slice(0, 12).map(([k, v]) => `${k}=${v}`).join('、');
    const notes = (result.notes || []).slice(0, 4).join('、');
    return `${sourceLabel || '文字'}已讀取，約 ${_dashboardAgentReportText.length} 字。${fields.length ? `初步抓到 ${fields.length} 個欄位：${names}` : '目前沒有抓到可套用欄位'}。${notes ? `需人工確認：${notes}。` : ''}若要覆蓋到 patient context，請輸入「套用報告欄位」。`;
}
function dashboardAgentUploadFile(file){
    const input = document.getElementById('dashboardAgentFile');
    if(!file) return;
    if(file.size > 1024 * 1024){
        dashboardAgentAddMessage('agent', '檔案超過 1MB，請先貼上重點文字或拆成較小的文字檔。');
        if(input) input.value = '';
        return;
    }
    const reader = new FileReader();
    reader.onload = () => {
        const text = String(reader.result || '');
        dashboardAgentAddMessage('user', `上傳文字病理報告：${file.name}`);
        dashboardAgentAddMessage('agent', dashboardAgentPathologySummary(text, file.name));
        dashboardAgentRefreshContextMeter();
        if(input) input.value = '';
    };
    reader.onerror = () => {
        dashboardAgentAddMessage('agent', '無法讀取這個文字檔，請改用純文字 .txt 或直接貼上內容。');
        if(input) input.value = '';
    };
    reader.readAsText(file);
}
function dashboardAgentReply(text){
    const q = String(text || '').toLowerCase();
    const ctx = dashboardPatientContext();
    const support = deriveCrossSectionSupport(ctx.p);
    const toolId = dashboardAgentToolFromText(text);
    if(toolId) return dashboardAgentRunTool(toolId);
    if(/期|stage|ajcc|分期/.test(q)){
        const st = ctx.stage || {};
        const tnm = `${st.T || '?'}${st.N || '?'}${st.M || '?'}`;
        return { action:'apiGuide', reply:`目前 fallback 模式只能讀左側 Patient Context，不會套用範例分期。左側 TNM 為 ${tnm}。請使用 /api/calculate/staging-score 或接入 agent API 取得正式工具結果；若左側欄位不足，請先補 T/N/M。` };
    }
    if(/藥|drug|用藥|適應症|給付|健保|事審|自費/.test(q)){
        return { action:'apiGuide', reply:'目前 fallback 模式不直接產生藥物建議，也不使用範例病人資料。請以左側 Patient Context 呼叫 agent API 或藥物查詢工具；若左側 ER/PR/HER2/TNM 不完整，需先補欄位。' };
    }
    if(/套用.*報告|報告.*套用|apply.*pathology/i.test(q)){
        if(!_dashboardAgentReportText) return '目前沒有已上傳或已貼上的病理報告文字。請先貼上文字或上傳 .txt。';
        if(!_lastPathologyParse) _lastPathologyParse = parseWorkspacePathologyReport(_dashboardAgentReportText);
        applyWorkspacePathologyParse();
        return '已將可辨識欄位套用到 patient context，請在左側欄位逐項確認。';
    }
    if(q.length > 600 && /er|pr|her2|ki-?67|grade|tumou?r|carcinoma|lymph|node|margin|乳|淋巴|切緣|病理/i.test(text)){
        return dashboardAgentPathologySummary(text, '貼上的病理報告');
    }
    if(/缺|missing|資料|欄位|檢查/.test(q)){
        const missing = support.missing.length ? support.missing.join('、') : '核心欄位目前足夠';
        const warnings = support.conflicts.length ? `；需檢核：${support.conflicts.slice(0, 3).join('、')}` : '';
        return `目前缺資料：${missing}${warnings}。可先回到分期與亞型補齊，再重新整理工具卡。`;
    }
    if(/健保|藥價|nhi|更新|web search|搜尋/.test(q)){
        return '健保藥價更新建議走院內或本機 agent：由 agent web search/下載健保署公告，比對 data/api 與 SQLite，產生差異摘要，再由維護者確認後更新 DB、匯出 Netlify read-only API。前端不直接寫資料庫。';
    }
    if(/api|端點|endpoint|呼叫|agent/.test(q)){
        return '目前公開端點以 read-only 為主：/api/health、/api/drugs、/api/formulations、/api/calculate/risk-scores、/api/calculate/staging-score。正式 agent 呼叫建議帶 X-Contact-Email 與 X-Client-App；需要寫入時改走院內 authenticated backend。';
    }
    if(/病人|說明|plan|輸出|摘要/.test(q)){
        return '病人說明單可從 Patient treatment plan 產生，核心會包含分期/亞型、預計治療藥物與週期、健保/自費初步提示、待補檢查與可嘗試申請的資源。';
    }
    if(/病理|報告|切片|手術|抽取|貼上/.test(q)){
        return '目前可整理的欄位包括 age、size、grade、ER/PR/HER2、Ki-67、c/pTNM、SLNB/ALND 數量、margin、PNI/LVI、pCR/residual ca。正式抽取仍需人工確認；目前病理解析 Beta 已先從主畫面隱藏，之後可接 BERT 或院內抽取 API。';
    }
    if(/計算|分數|score|predict|ihc4|cts5|pepi|npi|magee/.test(q)){
        const can = [];
        if(ctx.p.age && ctx.p.size && ctx.p.grade) can.push('PREDICT/NPI');
        if(ctx.p.er && ctx.p.pr && ctx.p.her2 && ctx.p.ki67) can.push('IHC4/Magee');
        if(ctx.p.age && ctx.p.size && ctx.p.grade && ctx.p.nodes_pos) can.push('CTS5');
        if(ctx.p.pT || ctx.p.pN || ctx.p.post_nac_response) can.push('PEPI/RCB 相關欄位整理');
        return `目前可嘗試計算：${can.length ? can.join('、') : '核心欄位不足，請先補 age、size、grade、ER/PR/HER2、Ki-67、LN+'}。缺資料：${support.missing.slice(0, 6).join('、') || '無明顯缺漏'}。`;
    }
    if(/治療|給付|藥|nccn|evidence|指引/.test(q)){
        return `目前資料整理：${support.setting || '未設定'}；亞型：${support.subtype || '待判讀'}。可查詢的給付/資料重點：${support.coverage.slice(0, 2).join('、')}。Evidence block：${support.evidence}。`;
    }
    return `目前資料為 ${ctx.stage.T || '?'}${ctx.stage.N || '?'}${ctx.stage.M || '?'}、${ctx.subtype || '亞型待判讀'}、${ctx.phaseLabel}。你可以問欄位、貼上病理報告，或要求我整理可計算的分數與健保查詢項目。`;
}
