function ensureDashboardWidgetModal(){
    let overlay = document.getElementById('dashboardWidgetModal');
    if(overlay) return overlay;
    overlay = document.createElement('div');
    overlay.id = 'dashboardWidgetModal';
    overlay.className = 'dashboard-widget-modal';
    overlay.innerHTML = `<div class="dashboard-widget-modal-panel">
        <div class="dashboard-widget-modal-head">
            <div class="dashboard-widget-modal-title" id="dashboardWidgetModalTitle">Dashboard</div>
            <button type="button" class="dashboard-widget-modal-close" onclick="closeDashboardWidgetModal()" aria-label="關閉">×</button>
        </div>
        <div class="dashboard-widget-modal-body" id="dashboardWidgetModalBody"></div>
    </div>`;
    overlay.addEventListener('click', event => {
        if(event.target === overlay) closeDashboardWidgetModal();
    });
    document.body.appendChild(overlay);
    return overlay;
}
