function initDashboardWidgetContent(id){
    const calcTab = dashboardCalcTabForWidget(id);
    if(calcTab){
        if(!_calcInited){ initCalcPage(); _calcInited=true; }
        syncAllCalculatorsFromWorkspace();
        switchCalcTab(calcTab);
        return;
    }
    if(id === 'breastPage') initDashboardBreastPanel();
    if(id === 'inpatientPage'){
        syncInpatientInputsFromPatient();
        if(!_inpInited) initInpCalc();
        syncInpatientInputsFromPatient();
    }
    if(id === 'icdPage') initIcdPage();
    if(id === 'surgeryPage' && !_surgInited) initSurgeryList();
    if(id === 'wsPage' && !_wsInited){ initWorkspace(); _wsInited=true; }
    if(id === 'journeyPage'){
        updatePatientCenterRecordingServiceUi();
        renderPatientJourney();
    }
    if(id === 'calcPage'){
        if(!_calcInited){ initCalcPage(); _calcInited=true; }
        switchCalcTab(FEATURE_FLAGS.predict ? 'predict' : 'gail');
        syncAllCalculatorsFromWorkspace();
    }
    if(id === 'trialsPage'){
        const hasResults = typeof _lastTrialResults !== 'undefined' && _lastTrialResults && _lastTrialResults.length;
        syncTrialsFromWorkspace(!hasResults);
    }
}
function openDashboardWidgetModal(id){
    const widget = DASHBOARD_WIDGETS.find(w => w.id === id);
    const page = document.getElementById(dashboardPageIdForWidget(id));
    if(!widget || !page) return;
    const overlay = ensureDashboardWidgetModal();
    const body = document.getElementById('dashboardWidgetModalBody');
    const title = document.getElementById('dashboardWidgetModalTitle');
    if(!body || !title) return;
    closeDashboardWidgetModal(false);
    initDashboardWidgetContent(id);
    title.textContent = dashboardWidgetCardMeta(widget).title;
    page.classList.add('active', 'dashboard-modal-page');
    page.classList.remove('dashboard-widget');
    body.appendChild(page);
    overlay.classList.add('open');
    document.body.classList.add('modal-dashboard-open');
}
function closeDashboardWidgetModal(deactivate=true){
    const overlay = document.getElementById('dashboardWidgetModal');
    const body = document.getElementById('dashboardWidgetModalBody');
    const page = body ? body.querySelector('.dept-page') : null;
    if(page){
        const container = document.querySelector('.container');
        const footer = container ? container.querySelector('.site-footer') : null;
        page.classList.remove('dashboard-modal-page');
        if(deactivate) page.classList.remove('active');
        if(container) container.insertBefore(page, footer || null);
    }
    if(overlay) overlay.classList.remove('open');
    document.body.classList.remove('modal-dashboard-open');
    if(document.body.classList.contains('modal-dashboard-mode')) renderModalDashboardOverview();
}
