async function runApiGuideSmokeTest(){
    const out = document.getElementById('apiGuideSmokeResult');
    const sample = {age:55,size_mm:20,grade:2,nodes_pos:0,cT:'T2',cN:'N0',cM:'M0',er_hscore:270,pr_hscore:200,her2:'-',ki67:15};
    const calls = [
        {name:'health', url:'/api/health'},
        {name:'config', url:'/api/config'},
        {name:'stats', url:'/api/stats'},
        {name:'breast drugs', url:'/api/drugs?category=oncology_breast'},
        {name:'trastuzumab formulations', url:'/api/formulations?drug=trastuzumab'},
        {name:'risk scores', url:'/api/calculate/risk-scores', method:'POST', body:sample},
        {name:'staging score', url:'/api/calculate/staging-score', method:'POST', body:sample}
    ];
    if(out) out.textContent = 'Running...';
    const results = [];
    for(const call of calls){
        try {
            const res = await fetch(call.url, {
                method: call.method || 'GET',
                headers: call.body ? {'content-type':'application/json'} : undefined,
                body: call.body ? JSON.stringify(call.body) : undefined
            });
            const body = await res.json();
            let summary = '';
            if(Array.isArray(body)) summary = `${body.length} rows`;
            else if(body.result && body.result.ajcc_v8) summary = `AJCC ${body.result.ajcc_v8.selected}`;
            else if(body.scores) summary = Object.keys(body.scores).join(', ');
            else if(body.total != null) summary = `total ${body.total}`;
            else summary = body.ok ? 'ok' : Object.keys(body).slice(0, 4).join(', ');
            results.push({ name:call.name, ok:res.ok, status:res.status, summary });
        } catch(err){
            results.push({ name:call.name, ok:false, status:'ERR', summary:err.message });
        }
    }
    if(out) out.textContent = JSON.stringify(results, null, 2);
    return results;
}
