async function loadAgentSystemPrompt(){
    const el = document.getElementById('agentSystemPromptText');
    if(!el) return;
    if(el.dataset.loaded === '1') return;
    el.textContent = AGENT_SYSTEM_PROMPT_PUBLIC;
    try {
        const res = await fetch('/api/agent-prompt');
        if(res.ok){
            const data = await res.json();
            if(data && data.prompt){
                el.textContent = data.prompt;
                el.dataset.loaded = '1';
                return;
            }
        }
    } catch(e){}
    el.dataset.loaded = '1';
}
