const TOUCH_SKIP_EMPTY_OPTIONS = new Set(['ws_breast_surgery','ws_reconstruction_surgery']);
const MOBILE_WHEEL_SELECT_IDS = new Set([
    'ws_cT','ws_cN','ws_pT','ws_pN','ws_phase','ws_brca','ws_reconstruction_surgery',
    'ajcc_cT','ajcc_cN','ajcc_pT','ajcc_pN'
]);
function touchOptionLabel(option){
    const text = (option.textContent || '').trim();
    if(!option.value) return text === '請選擇…' ? '—' : text;
    if(text.includes('—')) return text.split('—')[0].trim();
    if(text.includes('(')) return text.split('(')[0].trim();
    return text || option.value;
}
function enhanceTouchSelect(select){
    if(!select || select.dataset.touchEnhanced === '1' || select.classList.contains('ajcc-hidden-select')) return;
    if(!isMobileAppShell()) return;
    const optionCount = select.options ? select.options.length : 0;
    if(optionCount < 2) return;
    if(MOBILE_WHEEL_SELECT_IDS.has(select.id) || optionCount > 6){
        select.classList.add('mobile-wheel-select');
        select.dataset.touchEnhanced = 'wheel';
        return;
    }
    const picker = document.createElement('div');
    picker.className = 'touch-picker';
    picker.dataset.for = select.id;
    Array.from(select.options).forEach(option => {
        if(!option.value && TOUCH_SKIP_EMPTY_OPTIONS.has(select.id)) return;
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.dataset.value = option.value;
        btn.textContent = touchOptionLabel(option);
        btn.title = (option.textContent || '').trim();
        btn.addEventListener('click', () => {
            select.value = option.value;
            dispatchCompatEvent(select, 'change');
            refreshTouchPickers();
        });
        picker.appendChild(btn);
    });
    select.classList.add('touch-select-backup');
    select.insertAdjacentElement('afterend', picker);
    select.addEventListener('change', refreshTouchPickers);
    select.dataset.touchEnhanced = '1';
}
function enhanceTouchPresetInput(input){
    if(!input || input.dataset.touchPresetEnhanced === '1') return;
    if(!isMobileAppShell()) return;
    const values = TOUCH_PRESET_VALUES[input.id];
    if(!values) return;
    const box = document.createElement('div');
    box.className = 'touch-presets';
    box.dataset.for = input.id;
    values.forEach(item => {
        const value = typeof item === 'object' ? String(item.value != null ? item.value : '') : String(item);
        const label = typeof item === 'object' ? String(item.label != null ? item.label : value) : value;
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.dataset.value = value;
        btn.textContent = label;
        btn.addEventListener('click', () => {
            input.value = input.value === value ? '' : value;
            dispatchCompatEvent(input, 'input');
            dispatchCompatEvent(input, 'change');
            refreshTouchPresets();
        });
        box.appendChild(btn);
    });
    input.insertAdjacentElement('afterend', box);
    input.addEventListener('input', refreshTouchPresets);
    input.dataset.touchPresetEnhanced = '1';
}
function clearTouchEnhancements(){
    document.querySelectorAll('.touch-picker, .touch-presets').forEach(el => el.remove());
    document.querySelectorAll('.touch-select-backup, .mobile-wheel-select').forEach(el => {
        el.classList.remove('touch-select-backup', 'mobile-wheel-select');
        delete el.dataset.touchEnhanced;
    });
    document.querySelectorAll('[data-touch-preset-enhanced]').forEach(el => {
        delete el.dataset.touchPresetEnhanced;
    });
}
function enhanceTouchInputs(){
    if(!isMobileAppShell()){
        clearTouchEnhancements();
        return;
    }
    document.querySelectorAll('#wsPage select, #ajccPage select:not(.ajcc-hidden-select)').forEach(enhanceTouchSelect);
    Object.keys(TOUCH_PRESET_VALUES).forEach(id => enhanceTouchPresetInput(document.getElementById(id)));
    refreshTouchPickers();
    refreshTouchPresets();
}
function refreshTouchPickers(){
    document.querySelectorAll('.touch-picker').forEach(picker => {
        const select = document.getElementById(picker.dataset.for);
        if(!select) return;
        picker.querySelectorAll('button').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.value === select.value);
        });
    });
}
function refreshTouchPresets(){
    document.querySelectorAll('.touch-presets').forEach(box => {
        const input = document.getElementById(box.dataset.for);
        if(!input) return;
        const value = String(input.value || '');
        box.querySelectorAll('button').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.value === value);
        });
    });
}
function setPatientField(key, value){
    if(key === 'axillary_surgery') value = normalizeAxillarySurgeryValue(value);
    _patient[key] = value;
    if(key === 'breast_surgery' && value !== 'SM') _patient.nipple_sparing = '';
    if(key === 'nipple_sparing' && value === 'yes') _patient.breast_surgery = 'SM';
    const nodeSplitChanged = ['sln_pos','sln_total','aln_pos','aln_total'].includes(key);
    const nodeTotalChanged = key === 'nodes_pos';
    if(nodeSplitChanged){
        normalizeWorkspaceNodeFields();
        normalizeWorkspaceStage();
    }
    if(nodeTotalChanged) normalizeWorkspaceNodeStageFromPositiveCount();
    if(['nodes_pos','nodes_total','cT','cN','cM','pT','pN','pM','T','N','M'].includes(key)) normalizeWorkspaceStage();
    savePatient();
    if(nodeSplitChanged || nodeTotalChanged) syncWorkspaceInputs(['nodes_pos','nodes_total','pN','T','N','M']);
    refreshTouchPickers();
    refreshTouchPresets();
    if(typeof syncWsGeneChips === 'function') syncWsGeneChips();
    refreshWorkspaceDerived();
    refreshDashboardResults();
    refreshInitialVisitChecklist();
    if(typeof syncWsQuickChips === 'function') syncWsQuickChips();
    syncAllCalculatorsFromWorkspaceIfActive(key);
    if(document.body.classList.contains('modal-dashboard-mode')) renderModalDashboardOverview();
}
function syncWorkspaceInputs(keys=Object.keys(PATIENT_DEFAULTS)){
    keys.forEach(k => {
        const el = document.getElementById('ws_'+k);
        if(el){
            const value = _patient[k] || '';
            if(k === 'axillary_surgery' && el.tagName === 'SELECT' && value.includes(',')){
                el.value = '';
            } else {
                el.value = value;
            }
        }
    });
    refreshTouchPickers();
    refreshTouchPresets();
    if(typeof syncWsGeneChips === 'function') syncWsGeneChips();
}
