function normalizeWorkspaceNodeFields(){
    const slnPos = _patient.sln_pos !== '' ? Number(_patient.sln_pos) : NaN;
    const slnTotal = _patient.sln_total !== '' ? Number(_patient.sln_total) : NaN;
    const alnPos = _patient.aln_pos !== '' ? Number(_patient.aln_pos) : NaN;
    const alnTotal = _patient.aln_total !== '' ? Number(_patient.aln_total) : NaN;
    const hasSplitNodes = Number.isFinite(slnPos) || Number.isFinite(slnTotal) || Number.isFinite(alnPos) || Number.isFinite(alnTotal);
    if(!hasSplitNodes) return;
    const pos = (Number.isFinite(slnPos) ? slnPos : 0) + (Number.isFinite(alnPos) ? alnPos : 0);
    const total = (Number.isFinite(slnTotal) ? slnTotal : 0) + (Number.isFinite(alnTotal) ? alnTotal : 0);
    _patient.nodes_pos = String(pos);
    if(total > 0) _patient.nodes_total = String(total);
    if(!_patient.pN){
        _patient.pN = pathologyNodeStageFromCount(pos, '');
    }
    if(Number.isFinite(slnTotal) && slnTotal > 0){
        const parts = axillarySurgeryParts(_patient.axillary_surgery);
        if(!parts.includes('SLNB')) parts.push('SLNB');
        _patient.axillary_surgery = normalizeAxillarySurgeryValue(parts);
    }
}
function normalizeWorkspaceNodeStageFromPositiveCount(){
    const raw = String(_patient.nodes_pos == null ? '' : _patient.nodes_pos).trim();
    if(raw === '') return;
    const n = Number(raw);
    if(!Number.isFinite(n)) return;
    const current = String(_patient.pN || '').trim();
    if(current && current !== 'Nx') return;
    _patient.pN = pathologyNodeStageFromCount(n, '');
}
function validateWorkspacePostOpNodes(p){
    p = p || {};
    const warnings = [];
    const has = key => p[key] !== '' && p[key] !== undefined && p[key] !== null;
    const num = key => has(key) ? Number(p[key]) : NaN;
    const nodesPos = num('nodes_pos');
    const nodesTotal = num('nodes_total');
    const slnPos = num('sln_pos');
    const slnTotal = num('sln_total');
    const alnPos = num('aln_pos');
    const alnTotal = num('aln_total');
    const add = text => { if(text && !warnings.includes(text)) warnings.push(text); };
    if(Number.isFinite(slnPos) && Number.isFinite(slnTotal) && slnPos > slnTotal) add(`SLN+ (${slnPos}) 不可大於 SLN total (${slnTotal})`);
    if(Number.isFinite(alnPos) && Number.isFinite(alnTotal) && alnPos > alnTotal) add(`ALN+ (${alnPos}) 不可大於 ALN total (${alnTotal})`);
    if(Number.isFinite(nodesPos) && Number.isFinite(nodesTotal) && nodesPos > nodesTotal) add(`LN+ (${nodesPos}) 不可大於 LN total (${nodesTotal})`);
    if(Number.isFinite(nodesPos) && Number.isFinite(slnPos) && slnPos > nodesPos) add(`SLN+ (${slnPos}) 不可大於總 LN+ (${nodesPos})`);
    if(Number.isFinite(nodesPos) && Number.isFinite(alnPos) && alnPos > nodesPos) add(`ALN+ (${alnPos}) 不可大於總 LN+ (${nodesPos})`);
    const hasAnySplitPos = Number.isFinite(slnPos) || Number.isFinite(alnPos);
    if(hasAnySplitPos && Number.isFinite(nodesPos)){
        const splitSum = (Number.isFinite(slnPos) ? slnPos : 0) + (Number.isFinite(alnPos) ? alnPos : 0);
        if(splitSum !== nodesPos) add(`SLN+ + ALN+ = ${splitSum}，與總 LN+ (${nodesPos}) 不一致`);
    }
    const hasAnySplitTotal = Number.isFinite(slnTotal) || Number.isFinite(alnTotal);
    if(hasAnySplitTotal && Number.isFinite(nodesTotal)){
        const splitTotal = (Number.isFinite(slnTotal) ? slnTotal : 0) + (Number.isFinite(alnTotal) ? alnTotal : 0);
        if(splitTotal > nodesTotal) add(`SLN total + ALN total = ${splitTotal}，不可大於 LN total (${nodesTotal})`);
    }
    if(Number.isFinite(nodesPos) && p.pN){
        const expected = pathologyNodeGroupFromCount(nodesPos);
        const actual = pathologyNodeGroupFromStage(p.pN);
        if(expected && actual && expected !== actual){
            add(`LN+ ${nodesPos} 通常對應 ${expected} group，但目前 pN=${p.pN}`);
        }
    }
    return warnings;
}
function isWorkspacePostNacPathology(p){
    p = p || {};
    return p.post_nac_prefix === 'yes' || p.phase === 'post_neoadjuvant_residual' || /^(yp|yc)/i.test(String(p.pT || p.T || ''));
}
function getWorkspaceStage(p){
    const col = document.getElementById('wsInputCol');
    const quickClinicalMode = !!(col && col.classList.contains('ws-quick-mode') && !col.classList.contains('ws-full-mode'));
    if(quickClinicalMode && p.cT && p.cN && p.cM) return { T:p.cT, N:p.cN, M:p.cM, kind:'cTNM' };
    if(p.pT && p.pN) return { T:p.pT, N:p.pN, M:p.cM || p.M || 'M0', kind:isWorkspacePostNacPathology(p) ? 'ypTNM' : 'pTNM' };
    if(p.cT && p.cN && p.cM) return { T:p.cT, N:p.cN, M:p.cM, kind:'cTNM' };
    if(p.T && p.N && p.M) return { T:p.T, N:p.N, M:p.M, kind:'TNM' };
    return {
        T: p.pT || p.cT || p.T || '',
        N: p.pN || p.cN || p.N || '',
        M: p.cM || p.M || '',
        kind: (p.pT || p.pN) ? (isWorkspacePostNacPathology(p) ? 'ypTNM' : 'pTNM') : 'cTNM'
    };
}
function getWorkspaceStageForDisplay(p){
    p = p || {};
    const col = document.getElementById('wsInputCol');
    const quickClinicalMode = !!(col && col.classList.contains('ws-quick-mode') && !col.classList.contains('ws-full-mode'));
    if(quickClinicalMode && p.cT && p.cN && p.cM) return { T:p.cT, N:p.cN, M:p.cM, kind:'cTNM' };
    return getWorkspaceStage(p);
}
function refreshWorkspaceDerived(){
    let p = _patient;
    const st = getWorkspaceStage(p);
    if(st.T && st.N && st.M) p = { ...p, T: st.T, N: st.N, M: st.M, stageKind: st.kind };
    // BSA (Mosteller)
    const h = +p.height, w = +p.weight;
    const bsa = (h>0 && w>0) ? Math.sqrt(h*w/3600) : null;
    const bsaEl = document.getElementById('ws_d_bsa');
    if(bsaEl) bsaEl.textContent = bsa ? bsa.toFixed(2)+' m²' : '—';
    // CrCl (Cockcroft-Gault)
    const age=+p.age, scr=+p.scr;
    let crcl = null;
    if(age>0 && w>0 && scr>0){
        crcl = ((140-age)*w / (72*scr)) * (p.sex==='F' ? 0.85 : 1);
    }
    const crclEl = document.getElementById('ws_d_crcl');
    if(crclEl) crclEl.textContent = crcl ? crcl.toFixed(0)+' mL/min' : '—';
    // Molecular subtype is shown only in the AJCC v8 prognostic card.
    const subtypeEl = document.getElementById('ws_d_subtype');
    if(subtypeEl) subtypeEl.textContent = deriveWorkspaceSubtype(p) || '—';
    syncWorkspacePostNacVisibility();
    renderWorkspaceHomeSummary(p);
    renderWorkspaceStageSummary(p);
    renderWorkspacePatientContext();
}
