function _stageBucket(anat, M){
    if(M==='M1') return 'metastatic';
    if(['IIIA','IIIB','IIIC'].includes(anat)) return 'advanced';
    if(['IIA','IIB'].includes(anat)) return 'early';
    if(['IA','IB'].includes(anat)) return 'early';
    return null;
}
function refreshNHIEligibility(){
    const p = _patient;
    const el = document.getElementById('ws_nhi_eligible');
    if(!el) return;
    if(typeof FEATURE_FLAGS !== 'undefined' && !FEATURE_FLAGS.nhiReverseLookup){
        el.innerHTML = '<div class="ws-empty">健保給付反向查詢為 Beta 功能，目前已關閉。請至功能選單或 Agent 設定開啟。</div>';
        return;
    }
    if(typeof breastDrugs==='undefined' || !breastDrugs.length){
        el.innerHTML = '<div class="ws-empty">藥物資料尚未載入</div>'; return;
    }
    if(!p.T||!p.N||!p.M||!p.her2||!p.er){
        el.innerHTML = '<div class="ws-empty">請至少填入 T、N、M、ER、HER2 五項才能比對</div>';
        return;
    }
    const anat = _ajccAnatomic(p.T, p.N, p.M);
    const bucket = _stageBucket(anat, p.M);
    const her2Status = p.her2==='+' ? 'positive' : 'negative';
    const erprStatus = (p.er==='+'||p.pr==='+') ? 'positive' : 'negative';
    const items = [];
    breastDrugs.forEach(d => {
        const tags = d.clinical_tags||{};
        const stages = (d.stage||'').split(',');
        const reasons = [];
        let score = 0; // 0=ineligible, 1=partial, 2=fully matches
        // Stage match
        const stageMatch = stages.some(s => s===bucket);
        if(stageMatch) { score++; reasons.push(`分期符合 (${bucket})`); }
        else if(stages.length===0 || stages[0]==='') reasons.push('未指定分期');
        else { reasons.push(`分期不符 (藥物：${d.stage}，病人：${bucket})`); return; }
        // HER2 match
        if(tags.her2){
            if(tags.her2===her2Status||tags.her2==='both'){ score++; reasons.push(`HER2 ${her2Status}`); }
            else { reasons.push(`HER2 不符`); return; }
        }
        // ER/PR match
        if(tags.er_pr){
            if(tags.er_pr===erprStatus||tags.er_pr==='both'){ score++; reasons.push(`ER/PR ${erprStatus}`); }
            else { reasons.push(`ER/PR 不符`); return; }
        }
        // Menopause
        if(tags.menopause && p.menopause){
            if(tags.menopause===p.menopause||tags.menopause==='both'){ reasons.push(`停經狀態符合`); }
            else { reasons.push(`停經狀態不符`); return; }
        }
        // BRCA (for olaparib etc.)
        if(tags.brca){
            if(isBrcaPositiveValue(p.brca)){ reasons.push('BRCA 帶因符合'); }
            else { reasons.push('需 BRCA 突變'); score = 0; }
        }
        const cls = score>=2 ? 'full' : (score===1?'partial':'ineligible');
        items.push({drug:d, reasons, cls, priorAuth: d.prior_auth});
    });
    if(!items.length){
        el.innerHTML = '<div class="ws-empty">無符合給付的藥物</div>'; return;
    }
    // Sort: full match first, then partial, ineligible last
    items.sort((a,b)=>{
        const order = {full:0, partial:1, ineligible:2};
        return order[a.cls] - order[b.cls];
    });
    function lineKey(it){
        const line = it.drug.therapy_line;
        if(line === 1 || line === '1') return '1';
        if(line === 2 || line === '2') return '2';
        if(line === 3 || line === '3') return '3';
        return 'other';
    }
    const lineLabels = {
        '1': '第一線 / 初始治療',
        '2': '第二線 / 後線治療',
        '3': '第三線以上',
        other: '未分線或特殊條件'
    };
    const buckets = { '1': [], '2': [], '3': [], other: [] };
    items.forEach(it => buckets[lineKey(it)].push(it));
    let shown = 0;
    let html = '<div class="nhi-line-groups">';
    ['1','2','3','other'].forEach(k => {
        const list = buckets[k];
        if(!list.length) return;
        html += `<div class="nhi-line-group">
          <div class="nhi-line-title">${lineLabels[k]} <span>${list.length} 筆</span></div>
          <div class="nhi-elig-list">`;
        list.slice(0, 12).forEach(it=>{
        const d = it.drug;
        const trade = d.trade_names ? ` <span style="color:var(--text-muted);font-weight:400">(${d.trade_names.split(',')[0]})</span>` : '';
        html += `<div class="nhi-elig-card ${it.cls==='full'?'':it.cls}">
            <div class="nhi-elig-name">${d.generic_name}${trade}</div>
            <div class="nhi-elig-tags">${it.reasons.map(r=>`<span class="nhi-elig-tag">${r}</span>`).join('')}${it.priorAuth?'<span class="nhi-elig-tag" style="background:#fee2e2;color:#991b1b">需事審</span>':''}</div>
            ${d.indication?`<div class="nhi-elig-reason">${d.indication.slice(0,80)}${d.indication.length>80?'…':''}</div>`:''}
        </div>`;
            shown++;
        });
        html += '</div>';
        if(list.length>12) html += `<div style="font-size:.74rem;color:var(--text-muted);margin-top:.35rem">此線別共 ${list.length} 筆，先顯示前 12 筆</div>`;
        html += '</div>';
    });
    html += '</div>';
    if(items.length>shown) html += `<div style="font-size:.78rem;color:var(--text-muted);margin-top:.4rem">共 ${items.length} 筆，已依線別分組顯示 ${shown} 筆</div>`;
    el.innerHTML = html;
}
