    const subtype = d.subtype || deriveWorkspaceSubtype(p) || '—';
    const side = ({L:'左側',R:'右側',B:'雙側'}[p.side] || '—');
    const therapyCandidates = d.support.candidates && d.support.candidates.length ? d.support.candidates : ['待醫療團隊依完整資料確認'];
