    const grade_val = (grade === 2 || grade === 3) ? 1 : 0;
    const her2_beta = (her2==='pos') ? 0.2413 : (her2==='neg' ? -0.0762 : 0);
    return 0.0089827 * age_mfp
         + 2.093446  * size_mfp
         + 0.6260541 * nodes_mfp
