function _buildIssueBody(module, type, desc, inputs, includeState){
    const lines = [];
    lines.push(`## 問題類型`);
    lines.push(`${type}`);
    lines.push(``);
    lines.push(`## 模組`);
    lines.push(`${module}`);
    lines.push(``);
    lines.push(`## 描述`);
    lines.push(desc || '(未填)');
    lines.push(``);
    if(inputs && inputs.trim()){
        lines.push(`## 當時輸入的數值`);
        lines.push(inputs);
        lines.push(``);
    }
    lines.push(`## 環境資訊`);
    lines.push(`- App 版本: ${APP_VERSION}`);
    lines.push(`- URL: ${window.location.href}`);
    lines.push(`- User Agent: ${navigator.userAgent}`);
    lines.push(`- 螢幕: ${screen.width} x ${screen.height}`);
    lines.push(`- 時間: ${new Date().toISOString()}`);
    lines.push(``);
    if(includeState){
        try {
            const safePatient = {...(_patient || {})};
            // Strip potential PII even if user opted in
            delete safePatient.mrn; delete safePatient.name;
            lines.push(`## Workspace 狀態（已移除 MRN/姓名）`);
            lines.push('```json');
            lines.push(JSON.stringify(safePatient, null, 2));
            lines.push('```');
            lines.push(``);
            lines.push(`## Feature Flags`);
            lines.push('```json');
            lines.push(JSON.stringify(FEATURE_FLAGS, null, 2));
            lines.push('```');
        } catch(e){
            lines.push(`(failed to capture state: ${e.message})`);
        }
    }
    return lines.join('\n');
}
function submitIssue(){
    const module = document.getElementById('issue_module').value;
    const typeEl = document.getElementById('issue_type');
    const typeText = typeEl.options[typeEl.selectedIndex].text;
    const typeVal = typeEl.value;
    const desc = document.getElementById('issue_desc').value.trim();
    const inputs = document.getElementById('issue_inputs').value.trim();
    const includeState = document.getElementById('issue_include_state').checked;
    if(!desc){ alert('請至少填「詳細描述」'); return; }
    const title = `[${module}] ${typeText}`;
    const body = _buildIssueBody(module, typeText, desc, inputs, includeState);
    const baseIssueUrl = `https://github.com/${GITHUB_REPO}/issues/new`;
    let url = `${baseIssueUrl}?title=${encodeURIComponent(title)}` +
              `&body=${encodeURIComponent(body)}`;
    // GitHub URL length limit ~8KB; truncate if needed
    if(url.length > 6500){
        if(navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(body).catch(()=>{});
        const truncatedBody = body.substring(0, 2500) + '\n\n...(訊息過長已截斷；完整內容已嘗試複製到剪貼簿，請手動貼上補充)';
        url = `${baseIssueUrl}` +
              `?title=${encodeURIComponent(title)}` +
              `&body=${encodeURIComponent(truncatedBody)}`;
    }
    const opened = window.open(url, '_blank', 'noopener');
    if(!opened){
        if(navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(body).catch(()=>{});
        window.location.href = url;
    }
    closeIssueReport();
}
function copyIssueReport(){
    const module = document.getElementById('issue_module').value;
    const typeEl = document.getElementById('issue_type');
    const typeText = typeEl.options[typeEl.selectedIndex].text;
    const desc = document.getElementById('issue_desc').value.trim();
    const inputs = document.getElementById('issue_inputs').value.trim();
    const includeState = document.getElementById('issue_include_state').checked;
    const title = `[${module}] ${typeText}`;
    const body = _buildIssueBody(module, typeText, desc, inputs, includeState);
    const text = `${title}\n\n${body}`;
    if(navigator.clipboard && navigator.clipboard.writeText){
        navigator.clipboard.writeText(text).then(()=>alert('已複製 issue 內容，可手動貼到 GitHub。')).catch(()=>alert(text));
    } else {
        alert(text);
    }
}
function markCopyConfirmed(trigger){
    const el = trigger || (typeof event !== 'undefined' ? event.currentTarget : null);
    if(!el || !el.classList) return;
    const icon = el.querySelector ? (el.querySelector('[aria-hidden="true"]') || el.querySelector('[data-copy-icon]')) : null;
    const restoreText = icon ? icon.textContent : (el.tagName === 'BUTTON' && String(el.textContent || '').trim().length <= 3 ? el.textContent : '');
    el.classList.remove('copy-confirmed');
    void el.offsetWidth;
    el.classList.add('copy-confirmed');
    if(icon) icon.textContent = '✓';
    else if(restoreText) el.textContent = '✓';
    window.setTimeout(() => {
        el.classList.remove('copy-confirmed');
        if(icon && restoreText) icon.textContent = restoreText;
        else if(restoreText) el.textContent = restoreText;
    }, 900);
}
function fallbackCopyText(value){
    const ta = document.createElement('textarea');
    ta.value = value;
    ta.setAttribute('readonly', '');
    ta.style.position = 'fixed';
    ta.style.left = '-9999px';
    ta.style.top = '0';
    document.body.appendChild(ta);
    ta.select();
    let ok = false;
    try { ok = document.execCommand && document.execCommand('copy'); } catch(e){ ok = false; }
    document.body.removeChild(ta);
    return ok;
}
function copyTextToClipboard(text, successMessage, trigger){
    const value = String(text || '').trim();
    if(!value) return;
    if(navigator.clipboard && navigator.clipboard.writeText){
        navigator.clipboard.writeText(value).then(() => {
            markCopyConfirmed(trigger);
        }).catch(() => {
            if(fallbackCopyText(value)) markCopyConfirmed(trigger);
        });
    } else {
        if(fallbackCopyText(value)) markCopyConfirmed(trigger);
    }
}
