/* ── Workspace Quick / Full Mode ── */
function setWsQuickMode(mode, instant=false){
    const col = document.getElementById('wsInputCol');
    if(!col) return;
    const nextMode = mode === 'full' ? 'full' : 'quick';
    const doSwap = ()=>{
        col.classList.add('ws-quick-mode');
        col.classList.toggle('ws-full-mode', nextMode === 'full');
        const wsQuickTab = document.getElementById('wsTabQuick');
        const wsFullTab = document.getElementById('wsTabFull');
        if(wsQuickTab) wsQuickTab.classList.toggle('active', nextMode === 'quick');
        if(wsFullTab) wsFullTab.classList.toggle('active', nextMode === 'full');
        if(nextMode === 'quick'){
            syncWsQuickChips();
        }
        try{ localStorage.setItem('_wsMode', nextMode); }catch(e){}
    };
    if(instant){ doSwap(); return; }
    doSwap();
    col.classList.add(nextMode === 'full' ? 'ws-full-expanding' : 'ws-full-collapsing');
    setTimeout(()=> col.classList.remove('ws-full-expanding', 'ws-full-collapsing'), 260);
}
