function _ajccNForCalc(n){
    if(['N0(i-)','N0(i+)'].includes(n)) return 'N0';
    if(['N1a','N1b','N1c'].includes(n)) return 'N1';
    return n;
}
function _ajccValidate(t,n,m){
    n = _ajccNForCalc(n);
    if(t==='Tis' && (n!=='N0' && n!=='')) return '原位癌 (Tis) 依定義無淋巴轉移；若 SLN 陽性，腫瘤需重新分類為微浸潤 (T1mi) 或更高。';
    if(t==='T0' && n==='N0' && m==='M0') return 'T0 N0 M0 通常表示無乳癌證據（無原發病灶 + 無淋巴 + 無遠端轉移）。請確認 T 期。';
    return null;
}
function _ajccTGroup(t){
    if(t==='Tis') return 'is';
    if(t==='T0') return 0;
    if(['T1mi','T1a','T1b','T1c'].includes(t)) return 1;
    if(t==='T2') return 2;
    if(t==='T3') return 3;
    if(t === 'T4' || ['T4a','T4b','T4c','T4d'].includes(t)) return 4;
    return null;
}
function _ajccNGroup(n){
    n = _ajccNForCalc(n);
    if(n==='N0') return 0;
    if(n==='N1mi') return '1mi';
    if(n==='N1') return 1;
    if(['N2a','N2b'].includes(n)) return 2;
    if(['N3a','N3b','N3c'].includes(n)) return 3;
    return null;
}
function _ajccAnatomic(t,n,m){
    if(m==='M1') return 'IV';
    const tg=_ajccTGroup(t), ng=_ajccNGroup(n);
    if(tg==='is') return ng===0?'0':'?';
    if(tg===null||ng===null) return '?';
    if(ng===3) return 'IIIC';
    if(tg===4) return 'IIIB';
    if(ng===2) return 'IIIA';
    if(tg===3&&(ng===1||ng==='1mi')) return 'IIIA';
    if(tg===3&&ng===0) return 'IIB';
    if(tg===2&&(ng===1||ng==='1mi')) return 'IIB';
    if(tg===2&&ng===0) return 'IIA';
    if((tg===1||tg===0)&&ng===1) return 'IIA';
    if((tg===1||tg===0)&&ng==='1mi') return 'IB';
    if(tg===1&&ng===0) return 'IA';
    return '?';
}
function _renderAJCCPanel(t,n,m,elId,label){
    const el=document.getElementById(elId);
    if(!el) return null;
    if(!t||!n||!m){
        el.style.border='2px dashed var(--border)';
        el.style.background='';
        el.innerHTML=`<div style="color:var(--text-faint);font-size:.85rem;text-align:center">請選擇<br>${label}T、${label}N、${label}M</div>`;
        return null;
    }
    // Validate combination
    const errMsg=_ajccValidate(t,n,m);
    if(errMsg){
        el.style.border='2px solid #ef4444';
        el.style.background='#fef2f2';
        el.innerHTML=`<div style="font-size:.78rem;color:#991b1b;font-weight:600;margin-bottom:.3rem">&#9888;&#65039; 組合不符</div>
            <div style="font-size:.82rem;color:#991b1b;text-align:center;line-height:1.5;padding:0 .6rem">${errMsg}</div>`;
        return '?';
    }
    const stage=_ajccAnatomic(t,n,m);
    const cfg={
        '0':{bg:'#f8fafc',bc:'#94a3b8',col:'#475569',lbl:'原位癌'},
        'IA':{bg:'#f0fdf4',bc:'#22c55e',col:'#166534',lbl:'早期'},
        'IB':{bg:'#f0fdf4',bc:'#22c55e',col:'#166534',lbl:'早期'},
        'IIA':{bg:'#fefce8',bc:'#eab308',col:'#854d0e',lbl:'局部'},
        'IIB':{bg:'#fefce8',bc:'#eab308',col:'#854d0e',lbl:'局部'},
        'IIIA':{bg:'#fff7ed',bc:'#f97316',col:'#c2410c',lbl:'局部晚期'},
        'IIIB':{bg:'#fff7ed',bc:'#f97316',col:'#c2410c',lbl:'局部晚期'},
        'IIIC':{bg:'#fff7ed',bc:'#f97316',col:'#c2410c',lbl:'局部晚期'},
        'IV':{bg:'#fef2f2',bc:'#ef4444',col:'#b91c1c',lbl:'轉移性'}
    };
    const c=cfg[stage]||{bg:'#f9fafb',bc:'#d1d5db',col:'#6b7280',lbl:''};
    el.style.border=`2px solid ${c.bc}`;
    el.style.background=c.bg;
    el.innerHTML=`<div style="font-size:.72rem;color:${c.col};font-weight:600;letter-spacing:.05em">${label}TNM 解剖期別</div>
        <div style="font-size:2.4rem;font-weight:900;color:${c.col};line-height:1.1">第 ${stage} 期</div>
        <div style="font-size:.8rem;color:${c.col};opacity:.75;margin-top:.1rem">${c.lbl}</div>
        <div style="font-size:.7rem;color:var(--text-faint);margin-top:.35rem">${t} &nbsp;·&nbsp; ${n} &nbsp;·&nbsp; ${m}</div>`;
    return stage;
}
function calcAJCC(){
    const ct=document.getElementById('ajccT').value;
    const cn=document.getElementById('ajccN').value;
    const cm=document.getElementById('ajccM').value;
    const pt=document.getElementById('ajccPT').value;
    const pn=document.getElementById('ajccPN').value;
    const pm=document.getElementById('ajccPM').value;
    const cStage = _renderAJCCPanel(ct,cn,cm,'ajccClinicalResult','c');
    const pStage = _renderAJCCPanel(pt,pn,pm,'ajccPathologicResult','p');
    const stage = pStage || cStage;
    if(!stage){
        document.getElementById('ajccBioSection').style.display='none';
        document.getElementById('ajccCatastrophic').style.display='none';
        document.querySelectorAll('#ajccRefTable tr[data-stage]').forEach(r=>r.classList.remove('ajcc-highlighted'));
        return;
    }
    // Biomarker section: hidden for IV (always IV), 0 (always 0), or when flag is off
    document.getElementById('ajccBioSection').style.display=(stage==='IV'||stage==='0'||!FEATURE_FLAGS.ajccPrognostic)?'none':'';
    // Highlight table rows
    document.querySelectorAll('#ajccRefTable tr[data-stage]').forEach(r=>r.classList.remove('ajcc-highlighted'));
    document.querySelectorAll(`#ajccRefTable tr[data-stage="${stage}"]`).forEach(r=>r.classList.add('ajcc-highlighted'));
    // 重大傷病 eligibility
    const cat=document.getElementById('ajccCatastrophic');
    cat.style.display='';
    const eligible=['IIA','IIB','IIIA','IIIB','IIIC','IV'].includes(stage);
    cat.innerHTML=eligible
        ?`<div style="background:#f0fdf4;border-left:3px solid #16a34a;padding:.5rem .8rem;border-radius:0 var(--r-sm) var(--r-sm) 0;font-size:.82rem;color:#166534">&#9989; <strong>重大傷病卡：符合申請資格</strong>（第 ${stage} 期，IIA 以上）</div>`
        :`<div style="background:#fefce8;border-left:3px solid #f59e0b;padding:.5rem .8rem;border-radius:0 var(--r-sm) var(--r-sm) 0;font-size:.82rem;color:#92400e">&#9888;&#65039; <strong>重大傷病卡：</strong>第 ${stage} 期通常不符合申請資格（需 IIA 期以上）</div>`;
    calcAJCCPrognostic();
}
function calcAJCCPrognostic(){
    const pt=document.getElementById('ajccPT').value;
    const pn=document.getElementById('ajccPN').value;
    const pm=document.getElementById('ajccPM').value;
    const ct=document.getElementById('ajccT').value;
    const cn=document.getElementById('ajccN').value;
    const cm=document.getElementById('ajccM').value;
    const usePath = !!(pt && pn && pm);
    const t=usePath ? pt : ct;
    const n=usePath ? pn : cn;
    const m=usePath ? pm : cm;
    const grade=document.getElementById('ajccGrade').value;
    const er=document.getElementById('ajccER').value;
    const pr=document.getElementById('ajccPR').value;
    const her2=document.getElementById('ajccHER2').value;
    const el=document.getElementById('ajccPrognosticResult');
    // AJCC v8 prognostic stage requires: T/N/M + Grade + ER + PR + HER2 (all 7 fields)
    if(!t||!n||!m||!grade||!er||!pr||!her2){
        el.innerHTML='<div style="color:var(--text-muted);font-size:.78rem;padding:.4rem">請完整填入 cTNM 或 pTNM，以及 Grade、ER、PR、HER2 七項，才能查 AJCC v8 預後期別。</div>';
        return;
    }
    const nCalc = _ajccNForCalc(n);
    const anat=_ajccAnatomic(t,nCalc,m);
    if(anat==='?'){
        el.innerHTML='<div class="ajcc-error">T/N/M 組合不合理，無法判定預後期別。</div>';
        return;
    }
    // HER2-low is not separately staged in AJCC v8 prognostic staging.
    const her2Use = (her2 === 'low') ? '-' : her2;
    const prog = _ajcc9Lookup(t, nCalc, m, grade, er, pr, her2Use);
    if(prog === null){
        el.innerHTML=`<div class="ajcc-error">查表失敗：T=${t}, N=${n}, M=${m}, G${grade}, ER${er}, PR${pr}, HER2=${her2}。請確認此組合是否屬於 AJCC v8 標準範圍。</div>`;
        return;
    }
    const changed = prog !== anat;
    // Determine direction
    const seq=['0','IA','IB','IIA','IIB','IIIA','IIIB','IIIC','IV'];
    const ai = seq.indexOf(anat), pi = seq.indexOf(prog);
    let mod = 'neutral', icon = '&#8596;', col = '#475569';
    if(pi < ai){ mod='favorable'; icon='&#9660;'; col='#166534'; }
    else if(pi > ai){ mod='unfavorable'; icon='&#9650;'; col='#b91c1c'; }
    el.innerHTML=`<div style="background:var(--surface);border:1px solid var(--border);border-radius:var(--r-sm);padding:.6rem .8rem;font-size:.82rem">
        <div style="margin-bottom:.3rem">
          <span style="font-weight:600;color:#1d4ed8">AJCC v8 預後期別（${usePath?'病理':'臨床'}）：</span>
          <span style="font-weight:800;font-size:1.1rem;color:${col}">第 ${prog} 期</span>
          ${changed?`<span style="color:${col};margin-left:.3rem;font-size:.78rem">（解剖 ${anat} → 預後 ${prog}）</span>`:'<span style="color:${col};margin-left:.3rem;font-size:.78rem">（與解剖期別相同）</span>'}
          <span style="color:${col};margin-left:.5rem">${icon}</span>
        </div>
        <div style="color:var(--text-muted);font-size:.74rem;margin-top:.3rem;line-height:1.5">
            &#9432; <strong>查表依據</strong>：AJCC 第八版乳癌預後期別表；正式分期請以 AJCC 第八版手冊 Table 48.2 及病理報告為準。<br>
            輸入：T=${t}, N=${n}, M=${m}, G${grade}, ER${er}, PR${pr}, HER2${her2}。
        </div>
    </div>`;
}

