    let csv='藥物名稱,商品名,分類,分期,適應症\\n';
    drugs.forEach(d=>{csv+='"'+d.generic_name+'","'+(d.trade_names||'')+'","'+d.specialty_id+'","'+(d.stage||'')+'","'+(d.indication||'').replace(/"/g,'""')+'"\\n'});
    const blob=new Blob(['\\uFEFF'+csv],{type:'text/csv;charset=utf-8'});
